   418  UA_StatusCode
   419  UA_Discovery_addRecord(UA_Server *server, const UA_String *servername,
   420                         const UA_String *hostname, UA_UInt16 port,
   421                         const UA_String *path, const UA_DiscoveryProtocol protocol,
   422                         UA_Boolean createTxt, const UA_String* capabilites,
   423                         size_t *capabilitiesSize) {
   424      if(!capabilitiesSize || (*capabilitiesSize > 0 && !capabilites))
   425          return UA_STATUSCODE_BADINVALIDARGUMENT;
   426
   427      size_t hostnameLen = hostname->length;
   428      size_t servernameLen = servername->length;
   429      if(hostnameLen == 0 || servernameLen == 0)
   430          return UA_STATUSCODE_BADOUTOFRANGE;
   431
   432      // use a limit for the hostname length to make sure full string fits into 63
   433      // chars (limited by DNS spec)
   434      if(hostnameLen+servernameLen + 1 > 63) { // include dash between servername-hostname
   435          UA_LOG_WARNING(server->config.logger, UA_LOGCATEGORY_SERVER,
   436                         "Multicast DNS: Combination of hostname+servername exceeds "
   437                         "maximum of 62 chars. It will be truncated.");
   438      } else if(hostnameLen > 63) {
   439          UA_LOG_WARNING(server->config.logger, UA_LOGCATEGORY_SERVER,
   440                         "Multicast DNS: Hostname length exceeds maximum of 63 chars. "
   441                         "It will be truncated.");
   442      }
   443
   444      if(!server->mdnsMainSrvAdded) {
   445          mdns_record_t *r =
   446              mdnsd_shared(server->mdnsDaemon, "_services._dns-sd._udp.local.",
   447                           QTYPE_PTR, 600);
   448          mdnsd_set_host(server->mdnsDaemon, r, "_opcua-tcp._tcp.local.");
   449          server->mdnsMainSrvAdded = UA_TRUE;
   450      }
   451
   452      // [servername]-[hostname]._opcua-tcp._tcp.local.
   453      char fullServiceDomain[63+24];
   454      createFullServiceDomain(fullServiceDomain, 63+24, servername, hostname);
   455
   456      UA_Boolean exists = UA_Discovery_recordExists(server, fullServiceDomain, port, protocol);
   457      if(exists == UA_TRUE)
   458          return UA_STATUSCODE_GOOD;
   459
   460      UA_LOG_INFO(server->config.logger, UA_LOGCATEGORY_SERVER,
   461                  "Multicast DNS: add record for domain: %s", fullServiceDomain);
   462
   463      // _services._dns-sd._udp.local. PTR _opcua-tcp._tcp.local
   464
   465      // check if there is already a PTR entry for the given service.
   466
   467      // _opcua-tcp._tcp.local. PTR [servername]-[hostname]._opcua-tcp._tcp.local.
   468      mdns_record_t *r = mdns_find_record(server->mdnsDaemon, QTYPE_PTR,
   469                                          "_opcua-tcp._tcp.local.", fullServiceDomain);
   470      if(!r) {
   471          r = mdnsd_shared(server->mdnsDaemon, "_opcua-tcp._tcp.local.", QTYPE_PTR, 600);
   472          mdnsd_set_host(server->mdnsDaemon, r, fullServiceDomain);
   473      }
   474
   475      /* The first 63 characters of the hostname (or less) */
   476      size_t maxHostnameLen = MIN(hostnameLen, 63);
   477      char localDomain[65];
   478      memcpy(localDomain, hostname->data, maxHostnameLen);
   479      localDomain[maxHostnameLen] = '.';
   480      localDomain[maxHostnameLen+1] = '\0';
   481
   482      // [servername]-[hostname]._opcua-tcp._tcp.local. 86400 IN SRV 0 5 port [hostname].
   483      r = mdnsd_unique(server->mdnsDaemon, fullServiceDomain, QTYPE_SRV, 600,
   484                       UA_Discovery_multicastConflict, server);
   485      mdnsd_set_srv(server->mdnsDaemon, r, 0, 0, port, localDomain);
   486
   487      // A/AAAA record for all ip addresses.
   488      // [servername]-[hostname]._opcua-tcp._tcp.local. A [ip].
   489      // [hostname]. A [ip].
   490      mdns_set_address_record(server, fullServiceDomain, localDomain);
   491
   492      // TXT record: [servername]-[hostname]._opcua-tcp._tcp.local. TXT path=/ caps=NA,DA,...
   493      if(createTxt) {
   494          char *pathChars = (char *)UA_alloca(path->length + 1);
   495          memcpy(pathChars, path->data, path->length);
   496          pathChars[path->length] = 0;
   497          mdns_create_txt(server, fullServiceDomain, pathChars, capabilites,
   498                          capabilitiesSize, UA_Discovery_multicastConflict);
   499      }
   500
   501      return UA_STATUSCODE_GOOD;
   502  }
