    63  mdns_record_add_or_get(UA_Server *server, const char *record, const char *serverName,
    64                         size_t serverNameLen, UA_Boolean createNew) {
    65      int hashIdx = mdns_hash_record(record) % SERVER_ON_NETWORK_HASH_PRIME;
    66      struct serverOnNetwork_hash_entry *hash_entry = server->serverOnNetworkHash[hashIdx];
    67
    68      while (hash_entry) {
    69          size_t maxLen;
    70          if (serverNameLen > hash_entry->entry->serverOnNetwork.serverName.length)
    71              maxLen = hash_entry->entry->serverOnNetwork.serverName.length;
    72          else
    73              maxLen = serverNameLen;
    74
    75          if (strncmp((char *) hash_entry->entry->serverOnNetwork.serverName.data, serverName, maxLen) == 0)
    76              return hash_entry->entry;
    77          hash_entry = hash_entry->next;
    78      }
    79
    80      if(!createNew)
    81          return NULL;
    82
    83      // not yet in list, create new one
    84      // todo: malloc may fail: return a statuscode
    85      struct serverOnNetwork_list_entry *listEntry =
    86              (serverOnNetwork_list_entry*)UA_malloc(sizeof(struct serverOnNetwork_list_entry));
    87      listEntry->created = UA_DateTime_now();
    88      listEntry->pathTmp = NULL;
    89      listEntry->txtSet = UA_FALSE;
    90      listEntry->srvSet = UA_FALSE;
    91      UA_ServerOnNetwork_init(&listEntry->serverOnNetwork);
    92      listEntry->serverOnNetwork.recordId = server->serverOnNetworkRecordIdCounter;
    93      listEntry->serverOnNetwork.serverName.length = serverNameLen;
    94      // todo: malloc may fail: return a statuscode
    95      listEntry->serverOnNetwork.serverName.data = (UA_Byte*)UA_malloc(serverNameLen);
    96      memcpy(listEntry->serverOnNetwork.serverName.data, serverName, serverNameLen);
    97      server->serverOnNetworkRecordIdCounter = UA_atomic_add(&server->serverOnNetworkRecordIdCounter, 1);
    98      if (server->serverOnNetworkRecordIdCounter == 0)
    99          server->serverOnNetworkRecordIdLastReset = UA_DateTime_now();
   100
   101      // add to hash
   102      // todo: malloc may fail: return a statuscode
   103      struct serverOnNetwork_hash_entry *newHashEntry =
   104              (struct serverOnNetwork_hash_entry*)UA_malloc(sizeof(struct serverOnNetwork_hash_entry));
   105      newHashEntry->next = server->serverOnNetworkHash[hashIdx];
   106      server->serverOnNetworkHash[hashIdx] = newHashEntry;
   107      newHashEntry->entry = listEntry;
   108
   109      LIST_INSERT_HEAD(&server->serverOnNetwork, listEntry, pointers);
   110
   111      return listEntry;
